description = 'Basic rust function fibonacci'

[config]
# use default config

[context]
filepath = 'fibonacci.rs'
language = 'rust'
# indentation = '  ' # not specified
text = '''
fn fibonacci(├n: u32) -> u32 {
    if n == 0 {
        0
    } else if n == 1 {
        1
    } else {
        fibonacci(n - 1) + fibonacci(n - 2)
    }
}┤)
'''

[expected]
text = '''
fn fibonacci(├n: u32) -> u32 {
    if n == 0 {
        0
    } else if n == 1 {
        1
    } else {
        fibonacci(n - 1) + fibonacci(n - 2)
    }
}┤)╣
'''

description = 'Basic typescript function fibonacci'

[config]
# use default config

[context]
filepath = 'fibonacci.ts'
language = 'typescript'
# indentation = '  ' # not specified
text = '''
function fibonacci(n:├ number): number {
  if (n <= 1) {
    return n;
  }
  return fibonacci(n - 1) + fibonacci(n - 2);
}┤)
'''

[expected]
text = '''
function fibonacci(n:├ number): number {
  if (n <= 1) {
    return n;
  }
  return fibonacci(n - 1) + fibonacci(n - 2);
}┤)╣
'''

